/**
 * Generates the shadow C# file for a policy document: one static method per expression,
 * with `context` as the parameter, plus a source map from the generated file back to the
 * policy document.
 */

import type { Attribute, Document, Element, Expression, Node } from '../parser/ast';
import { lex } from '../parser/csharpLexer';
import { findNamedValues } from '../parser/scanner';
import type { Catalog, ChildDef, ElementDef } from '../policy/schema';
import { SourceMap, SourceMapBuilder, type OffsetRange } from '../sourceMap';

/** Namespaces APIM imports for every expression. */
export const IMPLICIT_USINGS = [
  'System',
  'System.Collections.Generic',
  'System.IO',
  'System.Linq',
  'System.Net',
  'System.Security.Cryptography',
  'System.Security.Cryptography.X509Certificates',
  'System.Text',
  'System.Text.RegularExpressions',
  'System.Xml',
  'System.Xml.Linq',
  'Newtonsoft.Json',
  'Newtonsoft.Json.Linq',
  'Apim.Policies',
];

export interface ShadowOptions {
  /** Lines before the usings, e.g. `#:package` directives. */
  header?: string;
  /** Lines after the usings and before the class, e.g. a top-level statement. */
  prelude?: string;
  /** Text appended after the class, e.g. inlined stubs. */
  footer?: string;
  /** Shown in the header comment. */
  sourceName?: string;
}

export interface ShadowMethod {
  name: string;
  expression: Expression;
  returnType: string;
  /** Generated range of the method's declaration, before the code. */
  headerRange: OffsetRange;
  /** Generated range of the expression's code. */
  codeRange: OffsetRange;
}

export interface Shadow {
  text: string;
  /** Maps generated offsets to policy document offsets. Scaffolding is unmapped. */
  map: SourceMap;
  methods: ShadowMethod[];
}

export function generateShadow(doc: Document, catalog: Catalog | undefined, options: ShadowOptions = {}): Shadow {
  const types = catalog ? returnTypes(doc, catalog) : new Map<Expression, string>();
  const b = new SourceMapBuilder();
  let text = '';
  const emit = (s: string) => {
    text += s;
    b.skip(s.length);
  };

  // The header comment sits in the file's leading trivia, where the SDK reads `#:` directives. A
  // path containing a line break would end the comment and inject directives, so only printable
  // ASCII goes into it.
  const source = options.sourceName?.replace(/[^\x20-\x7e]/g, '?');
  emit(`// <auto-generated> APIM policy expressions${source ? ` from ${source}` : ''}. Do not edit.\n`);
  if (options.header) emit(options.header.endsWith('\n') ? options.header : `${options.header}\n`);
  emit(IMPLICIT_USINGS.map((u) => `using ${u};\n`).join(''));
  if (options.prelude) emit(options.prelude.endsWith('\n') ? options.prelude : `${options.prelude}\n`);
  emit('\nstatic class __ApimPolicy\n{\n');

  const methods: ShadowMethod[] = [];
  doc.expressions.forEach((expr, i) => {
    const name = `__E${i}`;
    const returnType = types.get(expr) ?? 'object';
    const { code, map } = rewriteNamedValues(expr);
    const headerStart = b.length;
    emit(`    static ${returnType} ${name}(IProxyRequestContext context)${expr.kind === 'expr' ? ' =>\n        ' : '\n    {'}`);
    const start = b.length;
    text += code;
    b.embed(map, code.length);
    methods.push({ name, expression: expr, returnType, headerRange: { start: headerStart, end: start }, codeRange: { start, end: b.length } });
    emit(expr.kind === 'expr' ? ';\n' : '}\n');
  });

  emit('}\n');
  if (options.footer) emit(`\n${options.footer}`);
  return { text, map: b.build(), methods };
}

/** The shadow method whose code contains generated offset `gen` (end-inclusive). */
export function methodAt(shadow: Shadow, gen: number): ShadowMethod | undefined {
  return shadow.methods.find((m) => gen >= m.codeRange.start && gen <= m.codeRange.end);
}

/**
 * Replaces `{{name}}` outside string and char literals and comments with a call to
 * `NamedValues.Get`, returning the new code and its map to document offsets.
 */
function rewriteNamedValues(expr: Expression): { code: string; map: SourceMap } {
  const nvs = findNamedValues(expr.code, 0);
  if (nvs.length === 0) return { code: expr.code, map: expr.map };
  const literal: OffsetRange[] = [];
  for (const t of lex(expr.code)) {
    if (t.kind === 'string' || t.kind === 'char' || t.kind === 'comment') literal.push(t);
  }
  const inner = new SourceMapBuilder();
  let code = '';
  let at = 0;
  for (const nv of nvs) {
    if (literal.some((r) => nv.range.start >= r.start && nv.range.start < r.end)) continue;
    code += expr.code.slice(at, nv.range.start);
    inner.copy(at, nv.range.start - at);
    const call = `NamedValues.Get(${JSON.stringify(nv.name)})`;
    code += call;
    inner.opaque(nv.range.start, nv.range.end - nv.range.start, call.length);
    at = nv.range.end;
  }
  code += expr.code.slice(at);
  inner.copy(at, expr.code.length - at);
  return { code, map: SourceMap.compose(inner.build(), expr.map) };
}

/**
 * Only bool is typed. APIM converts other results (numbers, strings) loosely, so typing them
 * would report errors the gateway doesn't.
 */
const CSHARP_TYPES: Record<string, string> = { bool: 'bool' };

/** Return types for attribute expressions whose attribute has a declared type. */
function returnTypes(doc: Document, catalog: Catalog): Map<Expression, string> {
  const out = new Map<Expression, string>();
  const visit = (nodes: Node[], parentDef: ElementDef | undefined) => {
    for (const n of nodes) {
      if (n.type !== 'element') continue;
      const def = childDef(parentDef, n) ?? catalog.get(n.name);
      if (def) setTypes(n.attributes, def, out);
      visit(n.children, def);
    }
  };
  visit(doc.children, undefined);
  return out;
}

function childDef(parent: ElementDef | undefined, el: Element): ChildDef | undefined {
  return parent?.content.kind === 'children' ? parent.content.children.find((c) => c.name === el.name) : undefined;
}

function setTypes(attributes: Attribute[], def: ElementDef, out: Map<Expression, string>): void {
  for (const a of attributes) {
    const t = def.attributes?.find((d) => d.name === a.name)?.type;
    if (a.expression && t && CSHARP_TYPES[t]) out.set(a.expression, CSHARP_TYPES[t]);
  }
}
